rdig en voelt zich weinig thuis in een wereld waarin kracht telt. Hij ontmoet Achilles, de zoon van een koning en een zeegodin, die juist om zijn uitzonderlijke vermogens wordt bewonderd. Achilles neemt hem onder zijn hoede. Uit die ontmoeting groeit een band die verder gaat dan gewone vriendschap, terwijl hun verschillende afkomst en verwachtingen over heldendom op de achtergrond aanwezig blijven.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/130992/een-lied-voor-achilles.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/130992/een-lied-voor-achilles.html","sha256":"3e7ad445de63b74b9f7a1362f1621aa9cd2bb21d23fe4732db6a8765ab64146f","checkedAt":"2026-11-01T20:42:20.734Z","fact":"Paperback ISBN 9789041714879 verschijningsdatum 12/05/2023 NUR 302 Vertaalde literaire roman, novelle imprint Rainbow uitgever Uitgeverij Rainbow bv taal Nederlands","sourceAuthors":"Madeline Miller"},{"url":"https://metadata.isbn.nl/130992/een-lied-voor-achilles.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789083206776","key":{"id":978200149},"before":null,"after":{"id":978200149,"title":"Circe","isbn_10":null,"isbn_13":"9789083206776","work_id":978100052,"cover_id":null,"language":"nld","publisher":"Uitgeverij Orlando","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789083206776","key":{"edition_id":"@edition:9789083206776"},"before":null,"after":{"edition_id":"@edition:9789083206776","work_id":978100052,"bound_author_id":978300034,"bound_title":"Circe","bound_language":"nld","bound_isbn13":"9789083206776","for